#include <stdio.h>

// Without a pointer, this would only swap the local copies
void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

int main(void) {
    int x = 5;
    int y = 10;

    printf("Before swap: x=%d, y=%d\n", x, y);
    swap(&x, &y);   // pass addresses, not values
    printf("After swap:  x=%d, y=%d\n", x, y);

    return 0;
}
